INSERT INTO recipe_library (slug, name, category, servings, ingredients, steps) VALUES
  ('tarta-de-acelga', 'Tarta de acelga y ricota', 'Platos principales', 6, '[{"kind":"catalog","slug":"harina-de-trigo","grams":250},{"kind":"catalog","slug":"aceite-de-girasol","grams":40},{"kind":"catalog","slug":"acelga-cocida","grams":500},{"kind":"catalog","slug":"ricota","grams":250},{"kind":"catalog","slug":"huevo-entero","grams":150},{"kind":"catalog","slug":"cebolla-cruda","grams":110},{"kind":"catalog","slug":"queso-rallado","grams":30}]'::jsonb, 'Masa con la harina, el aceite y agua; estirar y forrar la tartera. Rehogar la cebolla, sumar la acelga escurrida, la ricota, los huevos y el queso. Rellenar y hornear 35 minutos a 180 °C.'),
  ('guiso-de-lentejas', 'Guiso de lentejas con vegetales', 'Platos principales', 4, '[{"kind":"catalog","slug":"lentejas-cocidas","grams":600},{"kind":"catalog","slug":"carne-picada-especial","grams":200},{"kind":"catalog","slug":"zanahoria-cruda","grams":120},{"kind":"catalog","slug":"cebolla-cruda","grams":110},{"kind":"catalog","slug":"morron-rojo","grams":120},{"kind":"catalog","slug":"zapallo-cocido","grams":300},{"kind":"catalog","slug":"pure-de-tomate","grams":250},{"kind":"catalog","slug":"aceite-de-oliva","grams":15}]'::jsonb, 'Rehogar cebolla, morrón y zanahoria en el aceite. Dorar la carne, sumar el puré de tomate, el zapallo en cubos y las lentejas. Cocinar 20 minutos a fuego bajo.'),
  ('pollo-al-horno-con-calabaza', 'Pollo al horno con calabaza y batata', 'Platos principales', 4, '[{"kind":"catalog","slug":"pechuga-pollo-cocida","grams":600},{"kind":"catalog","slug":"zapallo-cocido","grams":400},{"kind":"catalog","slug":"batata-hervida","grams":400},{"kind":"catalog","slug":"cebolla-cruda","grams":110},{"kind":"catalog","slug":"aceite-de-oliva","grams":20}]'::jsonb, 'Cortar la calabaza, la batata y la cebolla en trozos. Disponer con el pollo en una fuente, rociar con el aceite y hornear 45 minutos a 200 °C.'),
  ('merluza-con-pure-mixto', 'Merluza al horno con puré mixto', 'Platos principales', 2, '[{"kind":"catalog","slug":"merluza-cocida","grams":260},{"kind":"catalog","slug":"papa-hervida","grams":200},{"kind":"catalog","slug":"zapallo-cocido","grams":200},{"kind":"catalog","slug":"leche-descremada","grams":50},{"kind":"catalog","slug":"aceite-de-oliva","grams":10},{"kind":"catalog","slug":"limon","grams":15}]'::jsonb, 'Hornear los filetes con limón y aceite 15 minutos. Pisar la papa y el zapallo con la leche.'),
  ('fideos-con-salsa-y-carne', 'Fideos con salsa de tomate y carne', 'Platos principales', 4, '[{"kind":"catalog","slug":"fideos-cocidos","grams":800},{"kind":"catalog","slug":"carne-picada-especial","grams":300},{"kind":"catalog","slug":"pure-de-tomate","grams":400},{"kind":"catalog","slug":"cebolla-cruda","grams":110},{"kind":"catalog","slug":"aceite-de-oliva","grams":15},{"kind":"catalog","slug":"queso-rallado","grams":20}]'::jsonb, 'Rehogar la cebolla, dorar la carne y sumar el puré de tomate; cocinar 15 minutos. Servir sobre los fideos con el queso rallado.'),
  ('wok-de-pollo-y-vegetales', 'Wok de pollo, vegetales y arroz integral', 'Platos principales', 3, '[{"kind":"catalog","slug":"pechuga-pollo-cocida","grams":360},{"kind":"catalog","slug":"arroz-integral-cocido","grams":450},{"kind":"catalog","slug":"brocoli-cocido","grams":200},{"kind":"catalog","slug":"morron-rojo","grams":120},{"kind":"catalog","slug":"zanahoria-cruda","grams":120},{"kind":"catalog","slug":"champinones","grams":150},{"kind":"catalog","slug":"aceite-de-girasol","grams":15}]'::jsonb, 'Saltear el pollo en tiras con el aceite, sumar los vegetales en juliana y cocinar a fuego fuerte 5 minutos. Servir con el arroz.'),
  ('ensalada-completa-con-atun', 'Ensalada completa con atún y huevo', 'Ensaladas', 2, '[{"kind":"catalog","slug":"lechuga","grams":100},{"kind":"catalog","slug":"tomate-crudo","grams":250},{"kind":"catalog","slug":"zanahoria-cruda","grams":120},{"kind":"catalog","slug":"atun-al-agua","grams":120},{"kind":"catalog","slug":"huevo-duro","grams":100},{"kind":"catalog","slug":"choclo-cocido","grams":100},{"kind":"catalog","slug":"aceite-de-oliva","grams":15}]'::jsonb, 'Combinar los vegetales cortados con el atún escurrido, el huevo y el choclo. Condimentar con aceite y limón o vinagre.'),
  ('ensalada-de-quinoa-y-garbanzos', 'Ensalada de quinoa, garbanzos y palta', 'Ensaladas', 2, '[{"kind":"catalog","slug":"quinoa-cocida","grams":300},{"kind":"catalog","slug":"garbanzos-cocidos","grams":200},{"kind":"catalog","slug":"tomate-crudo","grams":150},{"kind":"catalog","slug":"pepino","grams":100},{"kind":"catalog","slug":"palta","grams":100},{"kind":"catalog","slug":"aceite-de-oliva","grams":10},{"kind":"catalog","slug":"limon","grams":15}]'::jsonb, 'Mezclar la quinoa y los garbanzos con los vegetales en cubos y la palta. Condimentar con aceite y limón.'),
  ('omelette-de-espinaca', 'Omelette de espinaca y queso', 'Desayunos y meriendas', 1, '[{"kind":"catalog","slug":"huevo-entero","grams":100},{"kind":"catalog","slug":"espinaca-cocida","grams":90},{"kind":"catalog","slug":"queso-cremoso","grams":30},{"kind":"catalog","slug":"aceite-de-oliva","grams":5}]'::jsonb, 'Batir los huevos, sumar la espinaca escurrida y cocinar en sartén con el aceite. Agregar el queso, doblar y servir.'),
  ('avena-cocida-con-banana', 'Avena cocida con banana y canela', 'Desayunos y meriendas', 1, '[{"kind":"catalog","slug":"avena-arrollada","grams":40},{"kind":"catalog","slug":"leche-descremada","grams":200},{"kind":"catalog","slug":"banana","grams":118},{"kind":"catalog","slug":"semillas-de-chia","grams":10}]'::jsonb, 'Cocinar la avena en la leche 5 minutos revolviendo. Servir con la banana en rodajas, la chía y canela a gusto.'),
  ('yogur-con-frutas-y-granola', 'Yogur con frutas y frutos secos', 'Desayunos y meriendas', 1, '[{"kind":"catalog","slug":"yogur-descremado-natural","grams":190},{"kind":"catalog","slug":"frutillas","grams":100},{"kind":"catalog","slug":"avena-arrollada","grams":20},{"kind":"catalog","slug":"nueces","grams":15},{"kind":"catalog","slug":"miel","grams":7}]'::jsonb, 'Servir el yogur con las frutillas, la avena, las nueces picadas y la miel.'),
  ('tostadas-con-palta-y-huevo', 'Tostadas integrales con palta y huevo', 'Desayunos y meriendas', 1, '[{"kind":"catalog","slug":"pan-integral","grams":56},{"kind":"catalog","slug":"palta","grams":50},{"kind":"catalog","slug":"huevo-entero","grams":50},{"kind":"catalog","slug":"tomate-crudo","grams":60}]'::jsonb, 'Tostar el pan, untar con la palta pisada y sumar el huevo a la plancha y rodajas de tomate.'),
  ('licuado-de-banana', 'Licuado de banana y avena', 'Bebidas', 1, '[{"kind":"catalog","slug":"leche-descremada","grams":250},{"kind":"catalog","slug":"banana","grams":118},{"kind":"catalog","slug":"avena-arrollada","grams":15}]'::jsonb, 'Licuar todo con hielo a gusto.'),
  ('hummus-con-bastones', 'Hummus con bastones de vegetales', 'Colaciones', 2, '[{"kind":"catalog","slug":"hummus","grams":100},{"kind":"catalog","slug":"zanahoria-cruda","grams":120},{"kind":"catalog","slug":"pepino","grams":100},{"kind":"catalog","slug":"morron-rojo","grams":80}]'::jsonb, 'Cortar los vegetales en bastones y servir con el hummus.')
